function StartQuiz({ dispatch, questionsLength }) {
  return (
    <div className="start">
      <h1>Welcome to the React Quiz!</h1>
      <p>{questionsLength} questions </p>
      <button className="btn" onClick={() => dispatch({ type: "START_QUIZ" })}>
        Start Quiz
      </button>
    </div>
  );
}

export default StartQuiz;
